[external_agent_tool_call: Bash]
description: Create placeholder folders for CESIRO SA and IPEC SA
command: "/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe" -NoProfile -Command "
\$firmeDir = 'Z:\00. Firme'
\$subs = @('01. Inregistrare ONRC','02. Certificat constatator','03. Act constitutiv','04. TVA','05. CI Administrator si Asociati','06. Contract sediu','07. Cont bancar','08. Hotarari AGA','09. Declaratii','10. Autorizatii si Avize','11. Contracte comerciale','12. MySMIS si Proiecte','13. Diverse','99. Arhiva')
foreach (\$firma in @('CESIRO SA - CUI TBD','IPEC SA - CUI TBD')) {
    \$firmaPath = Join-Path \$firmeDir \$firma
    if (-not (Test-Path -LiteralPath \$firmaPath)) { New-Item -ItemType Directory -Path \$firmaPath -Force | Out-Null }
    foreach (\$s in \$subs) {
        \$sp = Join-Path \$firmaPath \$s
        if (-not (Test-Path -LiteralPath \$sp)) { New-Item -ItemType Directory -Path \$sp -Force | Out-Null }
    }
    Write-Host \"Creat: \$firma\"
    # Si in 01. Acte Proprietate
    \$acteFirma = Join-Path 'Z:\01. Acte Proprietate\01. FIRME' \$firma
    if (-not (Test-Path -LiteralPath \$acteFirma)) { 
        New-Item -ItemType Directory -Path \$acteFirma -Force | Out-Null 
        New-Item -ItemType Directory -Path (Join-Path \$acteFirma '99. Arhiva') -Force | Out-Null
    }
}
" 2>&1 | tail -10
[/external_agent_tool_call]

