[external_agent_tool_call: Bash]
description: Clean up the erroneous files properly
command: "/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe" -NoProfile -Command "
\$firmeDir = 'Z:\00. Firme'
\$stersi = 0
\$folderFirme = Get-ChildItem -LiteralPath \$firmeDir -Directory | Where-Object { \$_.Name -match ' - CUI ' -and \$_.Name -notmatch '_1\$' -and \$_.Name -notmatch '^_' }
foreach (\$f in \$folderFirme) {
    Get-ChildItem -LiteralPath \$f.FullName -File -Recurse -Force -ErrorAction SilentlyContinue | Where-Object {
        (\$_.Name.StartsWith('_de-la-')) -or (\$_.Name.StartsWith('~\$'))
    } | ForEach-Object {
        Write-Host ('STERG: ' + \$_.FullName + ' [' + \$_.Length + ' b]')
        Remove-Item -LiteralPath \$_.FullName -Force
        \$stersi++
    }
}
Write-Host \"Total sterse: \$stersi\"
" 2>&1 | tail -30
[/external_agent_tool_call]

