description: Show C1b distribution
command: wc -l "Z:/00. Firme/_RAPORT_C1b_dubluri_in_sursa.csv" 2>/dev/null
"/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe" -NoProfile -Command "
\$c1 = Import-Csv 'Z:\00. Firme\_RAPORT_C1b_dubluri_in_sursa.csv'
Write-Host 'Total:' \$c1.Count
Write-Host '=== Top 10 pe folder de nivel 1 ==='
\$c1 | ForEach-Object {
    \$parts = \$_.Sursa -split '\\\\'
    if (\$parts.Count -ge 2) { \$parts[1] } else { 'necunoscut' }
} | Group-Object | Sort-Object Count -Descending | Select-Object -First 10 | ForEach-Object { '{0,-30} {1,6}' -f \$_.Name, \$_.Count }
Write-Host ''
Write-Host '=== Distributie per firma ==='
\$c1 | Group-Object Firma | Sort-Object Count -Descending | ForEach-Object { '{0,-40} {1,6}' -f \$_.Name, \$_.Count }
" 2>&1 | tail -35
[/external_agent_tool_call]

